'use strict';
const HumanUI=(()=>{
 const crest=house=>{const i=HumanOrigins.clans.findIndex(c=>c.id===house.id),colors=['#8a6f48','#6a7b69','#747487','#8c665f','#5c7f85'],c=colors[Math.max(0,i)%colors.length];return `<svg class="house-crest" viewBox="0 0 40 48" aria-hidden="true" shape-rendering="crispEdges"><path d="M4 3h32v27l-4 7-12 9-12-9-4-7Z" fill="${c}"/><path d="M8 7h24v21l-4 6-8 6-8-6-4-6Z" fill="none" stroke="#d8c794" stroke-width="2"/>${i%4===0?'<path d="M18 12h4v20h-4zM11 18h18v4H11z"':i%4===1?'<path d="M20 12l9 17H11z"':i%4===2?'<path d="M11 15h18v5H11zM11 25h18v5H11z"':'<path d="M17 12h6v6h6v6h-6v6h-6v-6h-6v-6h6z"'} fill="#ebdcae"/></svg>`};
 function birth(s){const h=s.humanOrigin;if(!h)return '';if(h.migrated)return `<section class="human-birth"><h3>บ้านสกุล${esc(s.household?.surname||s.name.split(' ').slice(1).join(' '))}</h3><p>${esc(s.household?.originNote||s.family)}</p><p class="human-fine">วัฒนธรรมในถิ่นที่อาศัย · ${esc(HumanOrigins.culture(h.ethnicityId).name)}</p></section>`;const house=HumanOrigins.clan(h.clanId,s),c=HumanOrigins.culture(h.ethnicityId),secondary=HumanOrigins.culture(h.secondaryId);return `<section class="human-birth">${typeof DynastyLife!=='undefined'?DynastyLife.panel(s):''}<div class="house-heading">${crest(house)}<div><small>${esc(HumanOrigins.classLabel(s))}</small><h3>สกุล${esc(house.name)}</h3><p>“${esc(house.motto)}”</p></div></div><p>${esc(house.story)}</p><dl class="human-origin-facts"><div><dt>รากวัฒนธรรม</dt><dd>${esc(c.name)}${secondary?' · '+esc(secondary.name):''}</dd></div><div><dt>ภาษาที่ได้ยินในบ้าน</dt><dd>${esc(c.language)}${secondary?' และ '+esc(secondary.language):''}</dd></div><div><dt>สิ่งที่บ้านส่งต่อ</dt><dd>${esc(house.assets)}</dd></div><div><dt>สิ่งที่อาจต้องรับมือ</dt><dd>${esc(house.burden)}</dd></div></dl><p class="human-fine">ถิ่นเดิมของสกุลอยู่ที่ ${esc(KINGDOMS[house.realm][0])}${house.realm!==s.kingdom?' · คุณเกิดในสาขาที่ '+esc(KINGDOMS[s.kingdom][0]):''} · เส้นทางชีวิตยังเป็นสิ่งที่คุณเลือกเองได้</p></section>`}
 function panel(s){const h=s.humanOrigin;if(!h)return '';const c=HumanOrigins.clan(h.clanId,s),p=HumanOrigins.path(h.path);return `<section class="panel human-path-strip"><div><small>${esc(HumanOrigins.culture(h.ethnicityId).name)} · ${h.migrated?'บ้านสกุล'+esc(s.household?.surname||''):'สกุล'+esc(c.name)}</small><strong>${p?'เส้นทาง · '+esc(p.name):'ชีวิตนี้ยังมีทางให้เลือก'}</strong></div><button class="secondary" data-human-open>${p?'ดูเส้นทาง / ตระกูล':'เลือกเส้นทางชีวิต'} →</button></section>`}
 function open(){const s=state,h=s.humanOrigin;if(!h)return;const house=HumanOrigins.clan(h.clanId,s),locked=s.dead||!s.accepted||s.calendar?.pending||s.outcome||Engine.biological(s)<12;modal(`<section class="human-dialog"><span class="eyebrow">ชาติพันธุ์ · ตระกูล · ชีวิตที่คุณเลือก</span><h2>คุณจะใช้ชีวิตแบบไหน?</h2><p class="human-fine">เส้นทางทำให้เรื่องที่พบและสิ่งที่ฝึกต่างกัน อาชีพเลือกเปลี่ยนได้จากเมนูงาน</p>${locked?'<p class="human-lock">'+(s.dead?'เรื่องของชีวิตนี้ถูกเก็บไว้แล้ว':Engine.biological(s)<12?'ตอนนี้ยังเป็นวัยเติบโต อ่านเส้นทางไว้ก่อนได้':'ตอบเหตุการณ์ที่ค้างอยู่ก่อนเปลี่ยนเส้นทาง')+'</p>':''}<div class="human-path-options">${HumanOrigins.paths.map(p=>`<button data-human-path="${p.id}" aria-pressed="${h.path===p.id}" ${locked||h.path===p.id?'disabled':''}><b>${esc(p.name)}${h.path===p.id?' · กำลังใช้ชีวิตเส้นทางนี้':''}</b><span>${esc(p.description)}</span><small>${h.progress[p.id]?'ผ่านจุดเปลี่ยน '+h.progress[p.id]+'/3':'มีเรื่องต่อเนื่องเฉพาะเส้นทาง'}</small></button>`).join('')}</div><div class="human-path-links"><button class="secondary" id="humanCareers">ดูอาชีพในเส้นทางนี้ →</button><button class="secondary" id="humanHouses">รู้จัก ${HumanOrigins.clans.length} ตระกูล →</button></div><details class="human-family-detail"><summary>บ้านสกุล${esc(h.migrated?s.household?.surname||'':house.name)}${h.migrated?'':' · ความไว้ใจ '+Math.round(h.favor)+'/100'}</summary>${birth(s)}${h.migrated?'':`<p class="human-fine">อิทธิพลเครือข่าย ${house.influence}/100 · ความไว้ใจของบ้านเปลี่ยนตามการตัดสินใจ</p>`}${!h.migrated&&house.gift>0?`<button class="secondary" id="humanGrant" ${HumanOrigins.canSupport(s)?'':'disabled'}>ขอทุนเริ่มต้น ${HumanOrigins.supportAmount(s)} ทอง · ความไว้ใจ −12</button><p class="human-fine">ขอได้ครั้งเดียวในชีวิตเมื่อโตพอและบ้านยังไว้ใจคุณ</p>`:''}</details></section>`);
  document.querySelectorAll('[data-human-path]').forEach(b=>b.onclick=()=>{if(HumanOrigins.choosePath(s,b.dataset.humanPath)){save();clock.reset();render();open();toast('บันทึกเส้นทางที่คุณอยากลองแล้ว')}});$('#humanHouses').onclick=()=>{modal(catalog(s));bindCatalog($('#modalBody'))};$('#humanCareers').onclick=()=>careers(h.path);if($('#humanGrant'))$('#humanGrant').onclick=()=>{if(HumanOrigins.support(s)){save();clock.reset();render();open();toast('ได้รับทุนจากบ้านแล้ว')}};
 }
 function catalog(s){const known=HumanOrigins.clans.filter(c=>WorldHistory.founding(c)<=WorldTimeline.year(s));return `<section class="human-clan-catalog"><span class="eyebrow">บ้านใหญ่และบ้านเล็กของผู้คน</span><h2>${known.length} ตระกูลที่มีบันทึกในยุคนี้</h2><p class="human-fine">อำนาจของตระกูลกับเงินส่วนตัวเป็นคนละส่วน สมาชิกแต่ละคนยังเลือกชีวิตที่ต่างจากบ้านได้</p><label class="world-search"><input id="clanSearch" type="search" placeholder="ค้นหาตระกูล ประเภท หรืออาณาจักร" aria-label="ค้นหาตระกูล"><span id="clanFound">${known.length} ตระกูล</span></label><div class="clan-cards">${known.map(c=>WorldHistory.house(c,WorldTimeline.year(s))).map(c=>`<article data-clan-card class="clan-card ${!s?.humanOrigin?.migrated&&s?.humanOrigin?.clanId===c.id?'is-mine':''}"><div class="house-heading">${crest(c)}<div><small>${esc(HumanOrigins.types.find(t=>t.id===c.type).label)}</small>${TierUI.badge(LifeTiers.humanTypes[c.type],'กำเนิด')}<h3>${esc(c.name)}</h3><p>${esc(KINGDOMS[c.realm][0])}</p></div></div><p>${esc(c.story)}</p><small>“${esc(c.motto)}” · อิทธิพล ${c.influence}/100</small><p class="human-fine">${esc(c.burden)}</p></article>`).join('')}</div></section>`}
 function bindCatalog(root=document){const input=root.querySelector('#clanSearch');if(input)input.oninput=()=>{let count=0;const q=input.value.trim();root.querySelectorAll('[data-clan-card]').forEach(c=>{c.hidden=!c.textContent.includes(q);if(!c.hidden)count++});root.querySelector('#clanFound').textContent=count+' ตระกูล'}}
 function bind(root=document){root.querySelectorAll('[data-human-open]').forEach(b=>b.onclick=open);bindCatalog(root)}
 return {birth,panel,open,catalog,bind,bindCatalog,crest};
})();
